echo 💡 For CPU-only: set CPU_ONLY_MODE=true before running
echo.
echo 🔄 Ghost Engine should connect automatically to enable chat and memory search

chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === 'queryMemories') {
    queryMemoriesFromCozoDB(request.query)
      .then(memories => ({
        success: true,
        memories: memories,
        summary: generateSummary(memories)
      }))
      .then(result => sendResponse(result))
      .catch(err => {
        console.error('[Sovereign] Error querying memories:', err);
        sendResponse({
          success: false,
          error: err.message,
          summary: null
        });
      });
    return true; // Keep channel open for async response
  }
});

async function queryMemoriesFromCozoDB(userInput) {
  try {
    // Attempt to hit the Local Bridge (webgpu_bridge.py)
    // The bridge runs on port 8080 if using start-bridge.bat, or random port 9000-9999
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout

    // Try ports for the bridge (8080 is the default when using start-bridge.bat, others are random)
    const commonPorts = [8080, 9000, 9001, 9002, 9003, 9004, 9005, 9006, 9007, 9008, 9009, 9010, 9011, 9012, 9013, 9014, 9015];
    let response = null;
    let lastError = null;

    for (const port of commonPorts) {
      try {
        // First, try to ping the health endpoint to see if there's a bridge running
        const healthUrl = `http://localhost:${port}/health`;
        let healthResponse;

        try {
          healthResponse = await fetch(healthUrl, {
            method: 'GET',
            signal: controller.signal
          });
        } catch (healthError) {
          console.log(`[Sovereign] Health check failed for port ${port}:`, healthError.message);
          continue; // Try next port
        }

        if (!healthResponse.ok) {
          console.log(`[Sovereign] Health check failed for port ${port}, status: ${healthResponse.status}`);
          continue; // Try next port
        }

        console.log(`[Sovereign] Bridge detected on port ${port}, testing memory search...`);

        // Now try the memory search endpoint
        const searchUrl = `http://localhost:${port}/memories/search`;

        // Try with the default token first
        response = await fetch(searchUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer sovereign-secret'  // Default token from start-bridge.bat
          },
          body: JSON.stringify({ query: userInput }),
          signal: controller.signal
        });

        if (response.ok) {
          console.log(`[Sovereign] Successfully connected to bridge at port ${port}`);
          clearTimeout(timeoutId);
          return response.json();
        } else if (response.status === 401) {
          // If unauthorized, try without token (some configurations might not require it)
          console.log(`[Sovereign] Trying without auth token for port ${port}`);
          response = await fetch(searchUrl, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({ query: userInput }),
            signal: controller.signal
          });

          if (response.ok) {
            console.log(`[Sovereign] Successfully connected to bridge at port ${port} (no auth)`);
            clearTimeout(timeoutId);
            return response.json();
          }
        }
      } catch (e) {
        lastError = e;
        console.log(`[Sovereign] Trying bridge port ${port} failed:`, e.message);
        continue;
      }
    }

    // If all ports failed, use the last error
    clearTimeout(timeoutId);
    throw lastError || new Error(`All bridge ports failed. No connection to WebGPU bridge available. Is the bridge running?`);
  } catch (e) {
    console.warn('[Sovereign] Backend unavailable, falling back to simulated response...', e.message);
    // In the future, this can connect directly to IndexedDB via shared worker
    // For now, return simulated data
    return [
      {
        content: "This is a simulated memory based on your input: " + userInput.substring(0, 100) + "...",
        timestamp: new Date().toISOString(),
        relevance: 0.8
      }
    ];
  }
}

function generateSummary(memories) {
  if (!memories || memories.length === 0) return null;

  const maxMemories = 3;
  const relevant = memories.slice(0, maxMemories);

  return relevant
    .map((m, idx) => `[Memory ${idx + 1}] ${m.content.substring(0, 150)}...`)
    .join('\n');
}

// Platform-specific DOM selectors
const SELECTORS = {
    'gemini.google.com': 'div[contenteditable="true"], textarea',
    'chatgpt.openai.com': 'textarea, div[contenteditable="true"]'
};

let textArea = null;
let inputTimeout = null;
const PAUSE_THRESHOLD = 3000; // 3 seconds

// 1. Detect the active text input
function detectTextArea() {
    const domain = window.location.hostname;
    const selector = SELECTORS[domain];
    if (!selector) return null;
    return document.querySelector(selector);
}

// 2. Extract text from the input
function getVisibleText() {
    if (!textArea) return "";
    return textArea.value || textArea.textContent || "";
}

// 3. Monitor for user pauses
function setupPauseDetector() {
    if (!textArea) return;

    textArea.addEventListener('input', () => {
        clearTimeout(inputTimeout);
        inputTimeout = setTimeout(() => {
            const text = getVisibleText();
            if (text.length > 10) { // Only query if meaningful text exists
                console.log('[Sovereign] 3-second pause detected, querying memories...');
                chrome.runtime.sendMessage(
                    { action: 'queryMemories', query: text },
                    (response) => {
                        if (response && response.success) injectContext(response);
                    }
                );
            }
        }, PAUSE_THRESHOLD);
    });
}

// 4. Inject the retrieved context
function injectContext(contextData) {
    if (!contextData.summary) return;

    const timestamp = new Date().toLocaleTimeString();
    const summary = `\n\n[Sovereign Context Injection at ${timestamp}]\n${contextData.summary}\n---\n`;

    // For contenteditable (Gemini/modern apps)
    if (textArea.isContentEditable || textArea.getAttribute('contenteditable') === 'true') {
        // Simple append - in production this might need Range/Selection manipulation for cursors
        textArea.textContent = textArea.textContent + summary;
    }
    // For standard textarea (ChatGPT legacy)
    else {
        textArea.value += summary;
    }

    // Notify user
    displayIndicator('\u2713 Context injected', 'success'); // Using Unicode checkmark
}

// 5. UI Feedback
function displayIndicator(message, type) {
    let indicator = document.getElementById('sovereign-indicator');
    if (!indicator) {
        indicator = document.createElement('div');
        indicator.id = 'sovereign-indicator';
        indicator.style.position = 'fixed';
        indicator.style.bottom = '20px';
        indicator.style.right = '20px';
        indicator.style.padding = '10px 15px';
        indicator.style.borderRadius = '5px';
        indicator.style.zIndex = '9999';
        indicator.style.fontFamily = 'monospace';
        document.body.appendChild(indicator);
    }

    indicator.textContent = message;
    indicator.style.background = type === 'success' ? '#238636' : '#da3633';
    indicator.style.color = '#ffffff';

    setTimeout(() => indicator.remove(), 5000);
}

// Handle messages from popup
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    if (request.action === 'testInjection') {
        // For testing purposes, inject a sample context
        const testData = {
            summary: "This is a test injection from Sovereign Context Bridge.\n\n[Sample Memory] Example context for testing purposes..."
        };
        injectContext(testData);
        sendResponse({ success: true });
        return true; // Keep channel open for async response
    }
});

// --- 6. Robust Initialization ---
function startSovereignObserver() {
    // Safety Check: If body isn't ready, wait for next frame
    if (!document.body) {
        console.warn("[Sovereign] document.body not ready, retrying...");
        requestAnimationFrame(startSovereignObserver);
        return;
    }

    console.log("[Sovereign] Body detected. Eyes opening...");

    // Main Logic
    if (!textArea) {
        textArea = detectTextArea();
        if (textArea) {
            console.log("[Sovereign] Input Found on Init.");
            setupPauseDetector();
        }
    }

    // Watch for dynamic changes
    const observer = new MutationObserver(() => {
        if (!textArea) {
            textArea = detectTextArea();
            if (textArea) console.log("[Sovereign] Input Found via Mutation.");
        }
    });

    observer.observe(document.body, { childList: true, subtree: true });
}

// Start only when DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', startSovereignObserver);
} else {
    startSovereignObserver();
}

// --- DEBUG: CLICK-TO-LOG REFLEX ---
// This allows us to manually verify what the extension sees when we touch the UI.
document.addEventListener('click', (event) => {
    const target = event.target;
    const detected = detectTextArea();

    console.group("👁️ [Sovereign Debug] Retina Scan");
    console.log("🖱️ Clicked Element:", target);
    console.log("🏷️ Clicked Class:", target.className);

    if (detected) {
        console.log("%c✅ Active Input Detected:", "color:green;font-weight:bold", detected);
        console.log("📝 Current Value:", detected.value || detected.innerText || detected.textContent);
    } else {
        console.log("%c❌ No Input Detected via Selector", "color:red;font-weight:bold");
        console.log("🔍 Current Selector for Domain:", SELECTORS[window.location.hostname] || "NONE");
    }
    console.groupEnd();
});

document.addEventListener('DOMContentLoaded', async () => {
    const statusBadge = document.getElementById('status-badge');

    // Check connection to Local Bridge
    try {
        // Using a more robust approach to handle CORS issues
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000); // 5 second timeout

        const res = await fetch('http://localhost:8080/health', {
            signal: controller.signal,
            mode: 'cors', // Explicitly set CORS mode
            credentials: 'omit' // Don't send credentials
        });

        clearTimeout(timeoutId);

        if (res.ok) {
            statusBadge.textContent = "● Online";
            statusBadge.className = "status-ok";
        } else {
            statusBadge.textContent = "● Offline";
            statusBadge.className = "status-err";
        }
    } catch (e) {
        // Handle network errors, CORS errors, and timeouts
        console.warn('[Sovereign] Backend connection failed:', e.message);
        statusBadge.textContent = "● Offline";
        statusBadge.className = "status-err";
    }

    document.getElementById('test-inject-btn').addEventListener('click', () => {
        // Trigger manual test injection
        chrome.tabs.query({active: true, currentWindow: true}, (tabs) => {
            chrome.tabs.sendMessage(tabs[0].id, { action: 'testInjection' }, (response) => {
                if (chrome.runtime.lastError) {
                    console.log('[Sovereign] Test injection not available on this page');
                } else {
                    console.log('[Sovereign] Test injection triggered');
                }
            });
        });
    });

    // Add settings button functionality
    document.getElementById('settings-btn').addEventListener('click', () => {
        // For now, just show a message - in the future this could open options page
        alert('Sovereign Context Bridge Settings\n\nConfigure extension preferences here.');
    });
});

#!/usr/bin/env python3
"""
GPU Resource Manager for ECE_Core
Provides utilities to monitor and manage GPU locks in the WebGPU bridge
"""

import requests
import json
import time
import argparse
from typing import Dict, Any

class GPUResourceManager:
    def __init__(self, bridge_url: str = "http://localhost:8080"):
        self.bridge_url = bridge_url
        self.headers = {"Authorization": "Bearer sovereign-secret"}
    
    def get_status(self) -> Dict[str, Any]:
        """Get current GPU status"""
        try:
            response = requests.get(f"{self.bridge_url}/v1/gpu/status", headers=self.headers)
            if response.status_code == 200:
                return response.json()
            else:
                print(f"Error getting status: {response.status_code} - {response.text}")
                return {}
        except Exception as e:
            print(f"Error connecting to bridge: {e}")
            return {}
    
    def reset_lock(self) -> bool:
        """Reset the current GPU lock"""
        try:
            response = requests.post(f"{self.bridge_url}/v1/gpu/reset", headers=self.headers)
            if response.status_code == 200:
                print("✅ GPU lock reset successfully")
                return True
            else:
                print(f"❌ Failed to reset GPU lock: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"❌ Error resetting GPU lock: {e}")
            return False
    
    def force_release_all(self) -> bool:
        """Force release all GPU locks (emergency)"""
        try:
            response = requests.post(f"{self.bridge_url}/v1/gpu/force-release-all", headers=self.headers)
            if response.status_code == 200:
                print("✅ All GPU locks force released successfully")
                return True
            else:
                print(f"❌ Failed to force release GPU locks: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"❌ Error force releasing GPU locks: {e}")
            return False
    
    def monitor(self, interval: int = 5):
        """Monitor GPU status continuously"""
        print(f"📊 Monitoring GPU status every {interval}s (Ctrl+C to stop)")
        try:
            while True:
                status = self.get_status()
                if status:
                    locked = status.get('locked', False)
                    owner = status.get('owner', 'None')
                    queue_depth = status.get('queue_depth', 0)
                    queued = status.get('queued', [])
                    
                    status_str = f"GPU: {'LOCKED' if locked else 'FREE'}"
                    if locked:
                        status_str += f" by {owner}"
                    if queue_depth > 0:
                        status_str += f" | Queue: {queue_depth} | Queued: {', '.join(queued) if queued else 'None'}"
                    
                    print(f"[{time.strftime('%H:%M:%S')}] {status_str}")
                else:
                    print(f"[{time.strftime('%H:%M:%S')}] ❌ Unable to get GPU status")
                
                time.sleep(interval)
        except KeyboardInterrupt:
            print("\n⏹️  Monitoring stopped")

def main():
    parser = argparse.ArgumentParser(description="GPU Resource Manager for ECE_Core")
    parser.add_argument("--bridge-url", default="http://localhost:8080", 
                       help="WebGPU bridge URL (default: http://localhost:8080)")
    parser.add_argument("--status", action="store_true", help="Get current GPU status")
    parser.add_argument("--reset", action="store_true", help="Reset GPU lock")
    parser.add_argument("--force-release", action="store_true", help="Force release all GPU locks")
    parser.add_argument("--monitor", action="store_true", help="Monitor GPU status continuously")
    parser.add_argument("--interval", type=int, default=5, help="Monitor interval in seconds (default: 5)")
    
    args = parser.parse_args()
    
    manager = GPUResourceManager(args.bridge_url)
    
    if args.status:
        status = manager.get_status()
        if status:
            print(json.dumps(status, indent=2))
        else:
            print("❌ Failed to get status")
    
    elif args.reset:
        manager.reset_lock()
    
    elif args.force_release:
        manager.force_release_all()
    
    elif args.monitor:
        manager.monitor(args.interval)
    
    else:
        # Default: show status
        status = manager.get_status()
        if status:
            locked = status.get('locked', False)
            owner = status.get('owner', 'None')
            queue_depth = status.get('queue_depth', 0)
            queued = status.get('queued', [])
            
            print(f"GPU Status: {'LOCKED' if locked else 'FREE'}", end="")
            if locked:
                print(f" by {owner}", end="")
            print(f" | Queue: {queue_depth} items")
            
            if queued:
                print(f"Queued: {', '.join(queued)}")
        else:
            print("❌ Failed to get status")

if __name__ == "__main__":
    main()

# Standard 004: WASM Memory Management

## What Happened?
WASM applications experienced "memory access out of bounds" errors and crashes when handling large JSON payloads or complex database operations. This was particularly problematic in `sovereign-db-builder.html` and `unified-coda.html` where JSON parameters were passed to `db.run()`.

## The Cost
- Crashes during database operations in browser-based CozoDB
- "Maximum call stack size exceeded" errors with large JSON payloads
- Unreliable memory operations in browser-based systems
- Hours of debugging memory access violations in WASM

## The Rule
1. **JSON Stringification:** Always properly stringify JSON parameters before passing to WASM functions:
   ```javascript
   // Before calling db.run() or similar WASM functions
   const jsonString = JSON.stringify(data);
   db.run(query, jsonString);
   ```

2. **Payload Size Limits:** Implement size checks before processing large JSON payloads in browser workers:
   ```javascript
   if (JSON.stringify(payload).length > MAX_SAFE_SIZE) {
       // Handle large payloads differently or chunk them
   }
   ```

3. **Error Handling:** Add timeout protection and fallback mechanisms for hanging WASM calls:
   ```javascript
   try {
       const result = await Promise.race([
           db.run(query),
           new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 10000))
       ]);
   } catch (error) {
       // Handle timeout or memory errors gracefully
   }
   ```

4. **IndexedDB Fallback:** Use `CozoDb.new_from_indexed_db` instead of `new_from_path` for persistent browser storage to avoid filesystem access issues.

# Standard 007: Model Loading Transition - Online-Only Implementation

## What Happened?
The Anchor Console (`chat.html`) was experiencing hangs during model loading after GPU configuration, while the Anchor Mic (`anchor-mic.html`) worked perfectly with the same models. The issue was in the complex model loading approach in `chat.html` that attempted to use local model files with bridge downloads, creating a problematic flow that caused the loading process to stall after GPU initialization.

The old implementation in `chat.html` was trying to:
1. Check for local model files using the `/models/{model}/resolve/main/` pattern
2. Download models through the bridge if not found locally
3. Use a complex configuration with multiple model entries and local file resolution

This approach was causing the loading process to hang after the GPU configuration step, preventing models from loading properly.

## The Cost
- Hours spent debugging model loading failures in `chat.html`
- Confusion between working and failing components (anchor-mic.html vs chat.html)
- Inconsistent model loading across different UI components
- User frustration with non-functional chat interface
- Time wasted on attempting to fix complex local model resolution logic
- Delayed development due to complex debugging of the local file + bridge download approach

## The Rule
1. **Online-Only Model Loading**: For reliable model loading, use direct online URLs instead of complex local file resolution:
   ```javascript
   // Use direct HuggingFace URLs like anchor-mic.html
   const appConfig = {
       model_list: [{
           model: "https://huggingface.co/" + selectedModelId + "/resolve/main/",
           model_id: selectedModelId,
           model_lib: modelLib,  // WASM library URL
           // ... other config
       }],
       useIndexedDBCache: false, // Disable caching to prevent issues
   };
   ```

2. **Simplified Configuration**: Use the same straightforward approach as `anchor-mic.html` instead of complex multi-model configurations with local file resolution.

3. **Archive Complex Logic**: When a complex model loading approach fails, archive it for future reference while implementing a working solution:
   ```javascript
   // Archive the old function with a descriptive name
   async function loadModel_archived() {
       // Original complex implementation
   }

   // Implement the working online-only approach
   async function loadModel() {
       // Simplified online-only implementation
   }
   ```

4. **Fallback to Working Patterns**: When debugging model loading issues, compare with known working implementations (like `anchor-mic.html`) and adopt their patterns.

5. **Progressive Enhancement**: Start with a working online-only solution, then add local model loading capabilities in a separate iteration after the basic functionality is stable.

6. **Model Loading Verification**: Always test model loading with the same models across different UI components to ensure consistency.

## Implementation Pattern

### Working Online-Only Format (Recommended):
```javascript
// Based on the working anchor-mic.html implementation
async function loadModel() {
    // ... setup code ...

    const appConfig = {
        model_list: [{
            model: "https://huggingface.co/" + selectedModelId + "/resolve/main/",
            model_id: selectedModelId,
            model_lib: modelLib,  // WASM library URL from mapper
            vram_required_MB: 2000,
            low_resource_required: true,
            buffer_size_required_bytes: gpuConfig.maxBufferSize,
            overrides: {
                context_window_size: gpuConfig.isConstrained ? 2048 : 4096
            }
        }],
        useIndexedDBCache: false, // Disable caching to prevent issues
    };

    engine = await CreateWebWorkerMLCEngine(
        new Worker('./modules/llm-worker.js', { type: 'module' }),
        selectedModelId,
        {
            initProgressCallback: (report) => {
                // Progress reporting
            },
            appConfig: appConfig,
            logLevel: "INFO",
            useIndexedDBCache: false, // Force disable cache
        }
    );
}
```

### Complex Local Resolution (Problematic - Avoid):
```javascript
// DO NOT USE - This causes hangs after GPU configuration
// Complex local file checking and bridge download logic
const localModelUrl = `${window.location.origin}/models/${safeStrippedId}/ndarray-cache.json`;
const check = await fetch(localModelUrl, { method: 'HEAD' });
// ... complex download and resolution logic that causes hangs
```

## Transition Protocol

When transitioning model loading implementations:

1. **Identify Working Component**: Find a UI component that successfully loads models (e.g., `anchor-mic.html`)
2. **Analyze Working Pattern**: Study the model loading approach in the working component
3. **Archive Complex Logic**: Preserve the old implementation for future reference
4. **Implement Simple Approach**: Adopt the working pattern from the successful component
5. **Test Thoroughly**: Verify the new implementation works with multiple models
6. **Document Changes**: Record the transition in standards documentation

## Future Considerations

The archived local model loading approach should be revisited after further prototyping and debugging. The online-only approach provides immediate functionality while the more complex local approach can be refined separately without blocking development progress.

# Standard 009: Model Loading Configuration - Bridge vs Direct Online

## What Happened?
The Anchor Console (`chat.html`) and other UI components were experiencing inconsistent model loading behavior. The system has two different model loading pathways:

1. **Bridge-based loading**: Uses `/models/{model_name}` endpoint which should redirect to local files or online sources
2. **Direct online loading**: Uses full HuggingFace URLs directly in the browser

The inconsistency occurred because:
- Some components (like `anchor-mic.html`) work with direct online URLs
- Other components (like `chat.html`) were configured for local file resolution
- The bridge redirect endpoint `/models/{model}/resolve/main/{file}` exists but may not be properly redirecting when local files don't exist

## The Cost
- Confusion about which model loading approach to use
- Inconsistent behavior across different UI components
- Models working in some components but not others
- Debugging time spent on understanding different loading mechanisms
- Users experiencing different model availability depending on which UI they use

## The Rule
1. **Consistent Model Configuration**: All UI components should use the same model loading approach:
   ```javascript
   // Recommended configuration pattern
   const modelConfig = {
       model: window.location.origin + `/models/${modelId}`,  // Will use bridge redirect
       model_id: `mlc-ai/${modelId}`,                        // Full HuggingFace ID
       model_lib: modelLib,                                  // WASM library URL
   };
   ```

2. **Bridge Redirect Logic**: The `/models/{model}/resolve/main/{file}` endpoint must:
   - First check for local files in the models directory
   - If local file doesn't exist, redirect to the corresponding HuggingFace URL:
     `https://huggingface.co/mlc-ai/{modelId}/resolve/main/{file}`

3. **Fallback Handling**: Implement proper fallback when local files are not available:
   ```javascript
   // In the UI, handle both local and online availability
   async function loadModel(modelId) {
       try {
           // Try bridge-based loading first
           await initializeEngine(bridgeConfig(modelId));
       } catch (error) {
           // Fallback to direct online loading if bridge fails
           await initializeEngine(onlineConfig(modelId));
       }
   }
   ```

4. **Testing Protocol**: Test model loading through both pathways:
   - Verify local file resolution works when files exist
   - Verify online fallback works when local files don't exist
   - Test both the redirect endpoint and direct access patterns

5. **Documentation Consistency**: All UI components should follow the same documented approach to avoid confusion.

# Standard: Model URL Construction and Availability Testing for MLC-LLM Integration

**Authority:** Active Standard | **Trigger:** Model Loading URL Construction Issues

## The Triangle of Pain

### 1. What Happened
The Anchor Console (`chat.html`) failed to load models with the error "TypeError: Failed to construct 'URL': Invalid URL", while the Root Mic (`anchor-mic.html`) loaded models successfully. The issue was in the dynamic model configuration where the system was constructing HuggingFace URLs instead of using the local path format expected by the MLC-LLM library. Additionally, model availability testing was needed to verify which models can be loaded before attempting to initialize the engine.

### 2. The Cost
- 3+ hours debugging model loading failures
- Confusion between working and failing components
- Inconsistent model loading across different UI components
- User frustration with non-functional chat interface
- Time wasted on attempting to load models that don't exist locally

### 3. The Rule
- **Full URL Format**: When configuring models for MLC-LLM, use full URL format with `window.location.origin`: `${window.location.origin}/models/{model-name}` instead of relative paths
- **Model ID Extraction**: Extract just the model name part from the full model ID using `selectedModelId.split('/').pop()`
- **Path Sanitization**: Sanitize model paths to remove special characters that could cause URL parsing errors: `path.replace(/[^a-zA-Z0-9._-]/g, '_')`
- **Consistent Format**: Ensure all dynamically added models follow the same URL pattern as pre-configured models in appConfig
- **Model Availability Testing**: Always verify model files exist locally before attempting engine initialization
- **URL Validation**: Always validate constructed URLs before passing to MLC-LLM engine

## Implementation Pattern

### Correct Format:
```javascript
// Predefined models in appConfig
const appConfig = {
    model_list: [
        {
            model: window.location.origin + "/models/Qwen2.5-Coder-1.5B-Instruct-q4f16_1-MLC",  // Full URL format
            model_id: "mlc-ai/Qwen2.5-Coder-1.5B-Instruct-q4f16_1-MLC",
            // ... other config
        }
    ]
};

// Dynamic model addition
const strippedModelId = selectedModelId.split('/').pop();
const safeModelPath = strippedModelId.replace(/[^a-zA-Z0-9._-]/g, '_'); // Sanitize path
appConfig.model_list.push({
    model: window.location.origin + `/models/${safeModelPath}`,  // Full URL format
    model_id: selectedModelId,                                   // Full HuggingFace ID
    model_lib: modelLib,                                        // WASM library URL
    // ... other config
});
```

### Model Availability Testing:
```javascript
// Test if model files exist before engine initialization
async function testModelAvailability(modelName) {
    const configFiles = [
        `/models/${modelName}/ndarray-cache.json`,
        `/models/${modelName}/tokenizer.json`,
        `/models/${modelName}/mlc-chat-config.json`
    ];

    for (const configFile of configFiles) {
        try {
            const response = await fetch(configFile, { method: 'HEAD' });
            if (response.status !== 200) {
                return { available: false, missingFile: configFile };
            }
        } catch (error) {
            return { available: false, error: error.message };
        }
    }
    return { available: true };
}
```

### Incorrect Format:
```javascript
// DO NOT USE - This causes "TypeError: Failed to construct 'URL'"
appConfig.model_list.push({
    model: `/models/${modelName}`,  // Relative path only
    // ...
});

// DO NOT USE - Without availability check
await CreateWebWorkerMLCEngine(worker, selectedModelId, { appConfig });
```

## File Renaming Standards

As part of this fix, the following files were renamed for consistency:
- `root-mic.html` → `anchor-mic.html` (Audio input interface)
- `root-dreamer.html` → `memory-builder.html` (Background processing)
- `sovereign-db-builder.html` → `db_builder.html` (Database management)

Update all references in HTML, documentation, and configuration files when renaming components.

## Model Availability Testing Protocol

Use the provided testing tools to verify model availability before attempting to load:

1. **Browser-based testing**: Use `tools/model_test.html` to test model accessibility via web interface
2. **Command-line testing**: Use `tools/test_model_loading.py` to test model availability programmatically
3. **Pre-loading verification**: Always check model availability before engine initialization
4. **Model download**: If model is not available locally, trigger download via `/v1/models/pull` endpoint

The testing tools verify:
- API endpoint accessibility
- Model path existence
- Required configuration files (ndarray-cache.json, tokenizer.json, mlc-chat-config.json)
- Overall system health

